/* Throwaway review prototype. No fetch, persistence, live ASR, or model inference. */
const sample = [
  ['00:00','很多研究汇报里，听众记住了术语，却没有记住研究要解决的问题。今天我想讨论，怎样在三分钟里把一个复杂研究讲清楚。'],
  ['00:38','我们通常会按自己的研究顺序介绍背景、方法和实验。但听众首先想知道的是：这个问题为什么值得关心？所以开场应该先建立共同的问题。'],
  ['01:12','例如，我们研究城市里的热环境。如果一上来介绍模型和参数，听众很难理解。不如先问：为什么同一个城市，相隔两条街，体感温度会差这么多？'],
  ['01:51','问题明确以后，再说清楚自己的核心主张：我们希望解释街区形态如何影响热环境。方法只保留与这个主张有关的信息，不需要把每个步骤都放进汇报。'],
  ['02:32','接下来给一个关键例子，帮助听众判断结论是否可信。数据要说明比较了什么、看到了什么，也要讲清研究的限制。这里的例子用于说明表达方式，并不是一次真实实验的报告。'],
  ['03:11','有人可能会问，三分钟里省略方法会不会损失严谨性？我的建议是把必要的方法保留，把详细过程放进备份页，留给问答环节。简洁和严谨可以通过信息层次来兼顾。'],
  ['03:58','结尾回到最初的问题，用一句话重申研究带来的认识，再告诉听众下一步是什么。这样，开场的问题和结尾的回答就有了对应关系。'],
  ['04:36','练习时，可以先不用幻灯片，向不熟悉课题的同学讲三分钟。请对方复述你研究的问题和结论。如果对方说不清，再调整表达结构。']
];
const variants = [['workspace','对照工作台'],['wizard','分步向导'],['reader','成果优先']];
const query = new URLSearchParams(location.search);
const state = {variant:variants.some(v=>v[0]===query.get('variant'))?query.get('variant'):'workspace',step:1,purpose:'summary',length:'standard',status:'idle',connection:{name:'我的示例连接',model:'示例文本模型',location:'remote',endpoint:'https://model.example.invalid'},connected:true,segments:sample.map(s=>[...s]),title:'把复杂研究讲清楚',version:1,custom:false,result:null,saved:false,editing:false,scenario:'success',error:'',timer:null,highlight:null,documentMode:'import'};
const app = document.getElementById('app');
const esc = value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const purposeName = p=>p==='summary'?'要点总结':'结构分析';
function titleBlock(){return `<div class="page-title"><div><span class="eyebrow">我的资料<span>/</span>文稿工作室</span><h1>${esc(state.title)}</h1><p>留下核心观点，让每一次表达都有迹可循。</p></div><div class="title-actions"><button data-action="sample" class="quiet">载入示例</button><button data-action="import">导入文字</button></div></div>`;}
function metadata(){return `<div class="meta-row"><span class="tag">${state.custom?'导入文字':'虚构演讲示例'}</span><span>文稿 v${state.version}</span><span>${state.segments.length} 个段落</span><span>${state.segments.reduce((n,s)=>n+s[1].length,0)} 字</span></div>`;}
function source(){return `<div class="source-scroll" id="source-scroll">${state.segments.map((s,i)=>`<article class="segment ${state.highlight===i?'highlight':''}" id="segment-${i}"><span class="timestamp">${esc(s[0]||String(i+1).padStart(2,'0'))}</span><p>${esc(s[1])}</p></article>`).join('')}</div>`;}
function sourcePanel(){return `<section class="panel"><div class="panel-head"><div><h2>原始文稿</h2><div class="panel-subtitle">${state.custom?'导入文字 · 尚无音频时间位置':'示例时间位置 · 未加载音频'}</div></div><button class="small quiet" data-action="edit-document">校对文稿</button></div><div class="panel-body" style="padding-bottom:10px">${metadata()}</div>${source()}<div class="source-foot">结果中的原文引用可定位到这里。${state.custom?'':'正式版支持点击文字回听。'}</div></section>`;}
function config(){return `<div class="config"><div class="purpose-tabs" role="group" aria-label="生成用途"><button data-purpose="summary" class="${state.purpose==='summary'?'active':''}" aria-pressed="${state.purpose==='summary'}">要点总结</button><button data-purpose="analysis" class="${state.purpose==='analysis'?'active':''}" aria-pressed="${state.purpose==='analysis'}">结构分析</button></div><p class="hint" style="margin-top:10px">${state.purpose==='summary'?'提炼核心观点，保留结论和原文依据。':'拆解问题、主张、例证与回应，理解表达结构。'}</p><div class="settings-grid"><label class="field">输出篇幅<select id="length"><option value="brief" ${state.length==='brief'?'selected':''}>简短 · 快速浏览</option><option value="standard" ${state.length==='standard'?'selected':''}>标准 · 保留关键说明</option></select></label><div class="field"><span>输出语言</span><div class="static-field">跟随原文<span>自动</span></div></div></div><div class="connection-inline"><div><strong>${state.connected?esc(state.connection.name):'尚未配置模型'}</strong><small>${state.connected?esc(state.connection.model)+' · '+(state.connection.location==='local'?'自己的电脑':'远程服务'):'先选择你使用的模型连接'}</small></div><button class="small quiet" data-action="connection">${state.connected?'更换':'配置'}</button></div><p class="send-note">${state.connection.location==='remote'?'正式接入后，所选文稿会发往该模型服务。':'正式接入后，所选文稿交给自己的电脑处理。'}本预览不发送内容。</p><div class="generate-row"><span class="hint">${state.custom?'已导入文字；示例模型不分析自定义内容。':'基于当前文稿 v'+state.version+' · 使用预设演示结果'}</span>${state.status==='generating'?(state.variant==='workspace'?'<button data-action="cancel">取消生成</button>':'<span class="hint">生成中…</span>'):`<button data-action="generate" class="primary" ${state.custom?'disabled':''}>${state.result?'重新生成':'生成'+purposeName(state.purpose)}</button>`}</div></div>`;}
function fixture(purpose,length){
  if(purpose==='summary')return {lead:'清楚的研究汇报，应围绕听众关心的问题组织信息，让问题、主张、证据与结尾形成连贯的路径。',blocks:[['先提出共同的问题','用具体疑问代替术语堆积，让听众先理解研究为什么值得关心。',[1,2]],['围绕主张安排信息','明确核心主张，只保留必要的方法与例证，并交代限制。',[3,4]],['用问答与复述检查表达','详细方法可放在备份页；练习时请听众复述问题与结论。',[5,7]]].slice(0,length==='brief'?2:3),note:'原文没有提出统一评分标准，也没有提供真实实验结论。'};
  return {lead:'这段表达沿着“指出问题 → 举例解释 → 提出主张 → 回应疑虑 → 给出练习方法”展开。',blocks:[['开场：建立共同问题','先指出“记住术语、没记住问题”的落差，再引出三分钟研究汇报的目标。',[0]],['例证：把抽象问题具体化','用城市街区温差的疑问，展示如何从听众能理解的现象切入。',[2]],['回应：处理可能的异议','主动回应简洁是否损害严谨性，并提出分层安排方法信息。',[5]],['收束：把建议变成行动','以听众复述作为练习反馈，让用户能够尝试并调整表达。',[7]]].slice(0,length==='brief'?2:4),note:'这是对可观察表达结构的解释，不代表演讲者真实的内部思考过程。'};
}
function resultText(){if(!state.result)return '';const r=state.result;return r.edited??`# ${purposeName(r.purpose)}\n\n${r.data.lead}\n\n${r.data.blocks.map(b=>`## ${b[0]}\n${b[1]}\n原文：${b[2].map(i=>sample[i][0]).join('、')}`).join('\n\n')}\n\n${r.data.note}`;}
function result(){
  let feedback='';
  if(state.status==='generating')feedback=`<div class="processing" role="status"><span class="eyebrow">正在生成 · 模拟过程</span><h3>正在整理${purposeName(state.purpose)}</h3><div class="progress-track"><span></span></div><p>原文稿会保留，你可以取消或等待示例结果。</p>${state.variant!=='workspace'?'<button data-action="cancel" class="small">取消生成</button>':''}</div>`;
  if(state.status==='failed')feedback=`<div class="error-box" role="alert"><strong>这次没有生成成功</strong>${esc(state.error)}<div style="margin-top:10px"><button class="small" data-action="connection">检查模型设置</button> <button class="small" data-action="retry">重试</button></div></div>`;
  if(!state.result)return feedback||(state.custom?'<div class="empty"><strong>文稿已就绪</strong><p>自定义内容不会套用示例分析。可校对文稿，或载入示例体验生成流程。</p></div>':'<div class="empty"><div class="empty-mark">≡</div><strong>重点从这里开始</strong><p>选择总结或结构分析，生成后可逐条查看原文依据。</p></div>');
  const r=state.result,stale=r.version!==state.version;
  let body=state.editing?`<label class="field">编辑结果<textarea id="result-editor" class="result-editor">${esc(resultText())}</textarea></label><div class="edit-actions"><button data-action="commit-edit" class="primary">确认修改</button><button data-action="cancel-edit">取消</button></div>`:r.edited!==undefined?`<div style="white-space:pre-wrap;line-height:1.9">${esc(r.edited)}</div><p class="hint">手动编辑版。请自行核对修改后的内容与原文是否一致。</p>`:`<p class="lead"><span class="lead-label">核心概述</span>${r.data.lead}</p>${r.data.blocks.map(b=>`<section class="result-block"><h3>${b[0]}</h3><p>${b[1]} ${b[2].map(i=>`<button class="citation" data-cite="${i}" aria-label="查看 ${sample[i][0]} 的原文">原文 ${sample[i][0]}</button>`).join('')}</p></section>`).join('')}<div class="note">${r.data.note}</div>`;
  const settingsChanged=r.purpose!==state.purpose||r.length!==state.length||r.model!==state.connection.model;
  return `${feedback}${stale?'<div class="warning" role="status">文稿已更新，此结果依据文稿 v'+r.version+'。重新生成前请载入原始示例，或在正式版连接模型。</div>':''}${settingsChanged?'<p class="warning">生成设置已调整，下方仍为上一次结果。重新生成后更新。</p>':''}<div class="result-heading"><div><span class="eyebrow">生成结果</span><h2>${purposeName(r.purpose)}</h2></div><span class="tag ${state.saved?'':'neutral'}">${state.saved?'已保存 · 本页内存':'待核对'}</span></div><p class="result-meta">文稿 v${r.version} · ${esc(r.model)} · ${r.length==='brief'?'简短':'标准'} · 示例结果</p>${body}${state.editing?'':`<div class="result-foot"><button data-action="edit-result" class="small">编辑结果</button><button data-action="save" class="small">保存结果</button><button data-action="copy" class="small">复制</button><button data-action="export" class="small">导出 Markdown</button></div>`}`;
}
function renderWorkspace(){return `${titleBlock()}<div class="workspace">${sourcePanel()}<section class="panel"><div class="panel-head"><div><h2>总结与分析</h2><div class="panel-subtitle">选择用途，再核对生成的内容</div></div><span class="tag neutral">文字模块</span></div><div class="panel-body">${config()}<div class="divider"></div>${result()}</div></section></div>`;}
function renderWizard(){const steps=['核对文稿','选择生成方式','核对与保存'];return `<div class="wizard-shell">${titleBlock()}<nav class="steps" aria-label="操作步骤">${steps.map((s,i)=>`<button class="step ${state.step===i+1?'active':''}" data-step="${i+1}" aria-current="${state.step===i+1?'step':'false'}"><span>${i+1}</span>${s}</button>`).join('')}</nav><section class="panel wizard-panel">${state.step===1?`<span class="eyebrow">第一步</span><h2>先看看文稿是否准确</h2><p class="hint">核对影响理解的句子即可，也可以直接继续。</p>${metadata()}${source()}<div class="wizard-bottom"><button data-action="edit-document">校对文稿</button><button class="primary" data-step="2">继续，选择用途 →</button></div>`:state.step===2?`<span class="eyebrow">第二步</span><h2>你希望从这份文稿得到什么？</h2>${config()}${state.status==='failed'?result():''}<div class="wizard-bottom"><button data-step="1">← 返回文稿</button>${state.result?'<button data-step="3">查看已有结果 →</button>':'<span class="hint">生成后进入结果页</span>'}</div>`:`<span class="eyebrow">第三步</span><h2>核对后，留下这次的重点</h2><div style="margin-top:24px">${result()}</div><details class="reader-source" ${state.highlight!==null?'open':''}><summary>展开原文，核对依据</summary>${source()}</details><div class="wizard-bottom"><button data-step="2">← 调整生成方式</button><span class="hint">保存与导出不会改动原文</span></div>`}</section></div>`;}
function renderReader(){return `${titleBlock()}<div class="reader-layout"><aside class="reader-nav"><div class="reader-nav-intro"><span class="eyebrow">当前资料</span><h3>${esc(state.title)}</h3><span class="hint">文稿 v${state.version} · ${state.segments.length} 个段落</span></div><button class="nav-item ${state.purpose==='summary'?'active':''}" data-purpose="summary"><span class="nav-glyph" aria-hidden="true">≡</span>要点总结<span class="nav-arrow" aria-hidden="true">↗</span></button><button class="nav-item ${state.purpose==='analysis'?'active':''}" data-purpose="analysis"><span class="nav-glyph" aria-hidden="true">⌘</span>结构分析<span class="nav-arrow" aria-hidden="true">↗</span></button><div class="future">后续扩展<br>语音陪练 · 宣传物料</div></aside><section class="panel reader-page"><div class="reader-toolbar"><span>${metadata()}</span><button class="small" data-action="edit-document">校对文稿</button></div><details ${!state.result?'open':''} id="reader-settings"><summary style="cursor:pointer;color:var(--green);margin-bottom:18px">生成设置</summary>${config()}<div class="divider"></div></details>${result()}<details class="reader-source" ${state.highlight!==null?'open':''}><summary>查看原始文稿与引用</summary>${source()}</details></section></div>`;}
function render(){app.innerHTML=({workspace:renderWorkspace,wizard:renderWizard,reader:renderReader}[state.variant])()+`<div class="state-line"><span>审核状态</span><strong>${({idle:'等待生成',generating:'生成中',completed:'结果已生成',failed:'生成失败',cancelled:'已取消'})[state.status]}</strong><span>文稿 v${state.version}</span><span>${state.result?'结果依据 v'+state.result.version:'尚无结果'}</span><span>${state.connected?'示例连接已选':'模型未配置'}</span><span>页面刷新后恢复示例</span></div>`;const idx=variants.findIndex(v=>v[0]===state.variant);document.getElementById('variant-count').textContent=(idx+1)+' / 3';document.getElementById('variant-name').textContent=variants[idx][1];document.getElementById('scenario').value=state.scenario;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3000);}
function changeVariant(delta){const i=variants.findIndex(v=>v[0]===state.variant);state.variant=variants[(i+delta+3)%3][0];const u=new URL(location.href);u.searchParams.set('variant',state.variant);history.replaceState({},'',u);render();}
function generate(){if(state.custom){toast('自定义文字需要正式连接模型后分析。');return;}if(state.editing){toast('请先确认或取消正在编辑的结果。');return;}clearTimeout(state.timer);if(!state.connected){state.status='failed';state.error='还没有选择模型连接。原文稿已保留，请先配置模型。';if(state.variant==='wizard')state.step=2;render();return;}const snapshot={purpose:state.purpose,length:state.length,model:state.connection.model,version:state.version,title:state.title};state.status='generating';if(state.variant==='wizard')state.step=3;render();state.timer=setTimeout(()=>{if(state.scenario==='timeout'){state.status='failed';state.error='示例超时：模型服务暂时没有回应。你可以调整设置后重试，无需再次转写。';}else{state.result={...snapshot,data:fixture(snapshot.purpose,snapshot.length)};state.status='completed';state.saved=false;}render();},1200);}
function documentModal(mode){state.documentMode=mode;document.getElementById('document-dialog-title').textContent=mode==='import'?'导入文字':'校对文稿';document.getElementById('document-name').value=mode==='import'?'':state.title;document.getElementById('document-text').value=mode==='import'?'':state.segments.map(s=>s[1]).join('\n\n');document.getElementById('document-dialog').showModal();}
document.addEventListener('click',async event=>{
  const btn=event.target.closest('button');if(!btn||btn.disabled)return;
  if(btn.dataset.purpose){if(state.status==='generating'||state.editing){toast('请先完成当前生成或编辑。');return;}state.purpose=btn.dataset.purpose;render();if(state.variant==='reader')document.getElementById('reader-settings').open=true;return;}
  if(btn.dataset.step){if(state.status==='generating'){toast('生成期间请等待或取消。');return;}if(state.editing){toast('请先确认或取消修改。');return;}state.step=Number(btn.dataset.step);render();return;}
  if(btn.dataset.cite!==undefined){state.highlight=Number(btn.dataset.cite);render();document.getElementById('segment-'+state.highlight)?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
  const action=btn.dataset.action;
  if(action==='previous'||action==='next'){if(state.editing){toast('请先确认或取消修改。');return;}changeVariant(action==='next'?1:-1);}
  if(action==='connection'){if(state.status==='generating'||state.editing){toast('请先完成或取消当前生成、编辑。');return;}const form=document.getElementById('connection-form');for(const key of ['name','model','location','endpoint'])form.elements[key].value=state.connection[key];form.elements.key.value='';document.getElementById('connection-feedback').textContent='';document.getElementById('connection-dialog').showModal();}
  if(action==='close-connection')document.getElementById('connection-dialog').close();
  if(action==='check-connection'){const f=document.getElementById('connection-form');if(f.reportValidity())document.getElementById('connection-feedback').textContent='示例字段完整；未进行真实连通性或模型能力验证。';}
  if(action==='import'||action==='edit-document'){if(state.status==='generating'||state.editing){toast('请先完成或取消当前操作。');return;}documentModal(action==='import'?'import':'edit');}
  if(action==='close-document')document.getElementById('document-dialog').close();
  if(action==='sample'){if(state.editing){toast('请先确认或取消修改。');return;}clearTimeout(state.timer);Object.assign(state,{segments:sample.map(s=>[...s]),title:'把复杂研究讲清楚',version:1,custom:false,result:null,saved:false,status:'idle',highlight:null,step:1});render();toast('已恢复虚构示例文稿。');}
  if(action==='generate')generate();
  if(action==='retry'){state.scenario='success';generate();}
  if(action==='cancel'){clearTimeout(state.timer);state.status='cancelled';render();toast('已取消；原文与已有结果均保留。');}
  if(action==='edit-result'){if(state.status==='generating'){toast('请等待或取消本次生成后再编辑。');return;}state.editing=true;render();document.getElementById('result-editor').focus();}
  if(action==='cancel-edit'){state.editing=false;render();}
  if(action==='commit-edit'){const text=document.getElementById('result-editor').value.trim();if(!text){toast('结果不能为空。');return;}state.result.edited=text;state.saved=false;state.editing=false;render();toast('修改已确认，请保存或导出。');}
  if(action==='save'){state.saved=true;render();toast('已保存到本页内存；需要长期保留请导出。');}
  if(action==='copy'){try{await navigator.clipboard.writeText(resultText());toast('已复制结果。');}catch{toast('当前浏览器不允许复制，请使用导出。');}}
  if(action==='export'){const blob=new Blob([resultText()+'\n'],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=state.result.title+'-'+purposeName(state.result.purpose)+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出 Markdown。');}
});
document.addEventListener('change',event=>{if(event.target.id==='length'){if(state.editing||state.status==='generating'){event.target.value=state.length;toast('请先完成当前操作。');return;}state.length=event.target.value;render();}if(event.target.id==='scenario'){if(state.editing||state.status==='generating'){event.target.value=state.scenario;toast('请先完成当前操作。');return;}state.scenario=event.target.value;if(state.scenario==='unconfigured'){state.connected=false;}render();}});
document.getElementById('connection-form').addEventListener('submit',event=>{event.preventDefault();const f=event.target;state.connection=Object.fromEntries(['name','model','location','endpoint'].map(k=>[k,f.elements[k].value.trim()]));state.connected=true;state.scenario='success';state.error='';state.status=state.result?'completed':'idle';f.elements.key.value='';document.getElementById('connection-dialog').close();render();toast('已选择示例连接；未调用真实服务。');});
document.getElementById('document-form').addEventListener('submit',event=>{event.preventDefault();const text=document.getElementById('document-text').value.trim(),name=document.getElementById('document-name').value.trim();if(!text||!name)return;const pieces=text.split(/\n\s*\n/).filter(Boolean);state.title=name;state.custom=pieces.length!==sample.length||pieces.some((p,i)=>p!==sample[i]?.[1]);state.segments=pieces.map((p,i)=>[state.custom?'':sample[i][0],p]);if(state.documentMode==='import'){state.version=1;state.result=null;}else{state.version++;}state.highlight=null;state.saved=false;state.status=state.result?'completed':'idle';document.getElementById('document-dialog').close();render();toast('文稿已更新为 v'+state.version+'。');});
document.addEventListener('keydown',event=>{if(document.querySelector('dialog[open]')||event.target.closest('input,textarea,select,[contenteditable]')||state.editing)return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();changeVariant(event.key==='ArrowRight'?1:-1);}});
render();
